using System;using System.IO;namespace Mapping{    /// <summary>    ///     /// </summary>    public abstract class MapConverterSkeleton : IMapConverter    {        /// <summary>        ///         /// </summary>        /// <param name="mapFile"></param>        /// <returns></returns>        public abstract MapData Read(string mapFile,bool isOrigianlMap=false);        /// <summary>        ///         /// </summary>        /// <param name="map"></param>        /// <param name="fileName"></param>        public virtual void Save(Map map, string fileName)        {            string url = string.Format("{0}", fileName);            FileStream fs = new FileStream(url, FileMode.Create, FileAccess.Write, FileShare.ReadWrite);            StreamWriter sw = new StreamWriter(fs);            sw.WriteLine("[MapSaveType]");//0            sw.WriteLine("[SubstrateID]");//2            sw.WriteLine(map.SubstrateID);//3            sw.WriteLine("[NullBin]");//4            sw.WriteLine(map.NullBin.ToString());//5            sw.WriteLine("[EmptyBin]");//6            sw.WriteLine(map.EmptyBin.ToString());//7            sw.WriteLine("[Bins]");//8            string bins = "";            if (map.Bins != null)            {                for (int i = 0; i < map.Bins.Count; i++)                {                    Bin bin = map.Bins[i];                    bins = string.Format("{0},{1}", bins, bin + "|" + bin.Color.A.ToString() + "|" + bin.Color.R.ToString() + "|" + bin.Color.G.ToString() + "|" + bin.Color.B.ToString() + "|" + bin.Work);                }            }            sw.WriteLine(bins);//9            sw.WriteLine("[BlockRows]");//10            sw.WriteLine(map.BlockRows.ToString());//11            sw.WriteLine("[BlockColumns]");//12            sw.WriteLine(map.BlockColumns.ToString());//13            sw.WriteLine("[RowsInBlock]");//14            sw.WriteLine(map.Rows.ToString());//15            sw.WriteLine("[ColumnsInBlock]");//16            sw.WriteLine(map.Columns.ToString());//17            sw.WriteLine("[ShotBins]");//18            string shotBins = "";            if (map.ShotBins != null)            {                for (int r = 0; r < map.Rows; r++)                {                    for (int c = 0; c < map.Columns; c++)                    {                        shotBins = string.Format("{0},{1}", shotBins, map.ShotBins[r, c]);                    }                }            }            sw.WriteLine(shotBins);//19            sw.WriteLine("[BinCodes]");//20            for (int br = 0; br < map.BlockRows; br++)            {                for (int bc = 0; bc < map.BlockColumns; bc++)                {                    for (int r = 0; r < map.Rows; r++)                    {                        string binCodes = "";                        for (int c = 0; c < map.Columns; c++)                        {                            Unit unit = map[br, bc, r, c];                            ////if (mapSaveType == MapSaveType.Wafer_WaferMap_MPW && unit.State == UnitState.Picked)                            ////{                            ////    binCodes = string.Format("{0},{1}", binCodes, map.EmptyBin.FormattedCode);                            ////}                            //else if (unit.State == UnitState.Bonded || unit.State == UnitState.Picked)                            //{                            //    binCodes = string.Format("{0},{1}", binCodes, map.NullBin.FormattedCode);                            //}                            //else                            //{                            //    binCodes = string.Format("{0},{1}", binCodes, unit.Bin.FormattedCode);                            //}                        }                        sw.WriteLine(binCodes);//21...                    }                }            }            sw.Flush();            sw.Close();            fs.Close();        }    }}